export const PROTECTION_POLICY=Object.freeze({usage:'local_noncommercial_research_only',commercialDistributionCleared:false,sourceUrl:'https://www.protectedplanet.net/',termsUrl:'https://www.protectedplanet.net/en/legal',commercialUrl:'https://www.ibat-alliance.org/',license:'Protected Planet terms; commercial permission required'});
