function shapeHeader(bytes){if(bytes.length<100||bytes.length%2)fail('shapefile_header_invalid');const v=view(bytes);if(v.getInt32(0)!==9994||v.getInt32(24)*2!==bytes.length||v.getInt32(28,true)!==1000)fail('shapefile_header_invalid');return v;}
